// Factory for additional country pages, filling every Destination field concisely.
function mkDest(p: {
  slug: string;
  name: string;
  region: string;
  image: string;
  tagline: string;
  overview: string;
  highlights: string[];
  bestTime: string;
  styles: string[];
  faqs?: { q: string; a: string }[];
}): Destination {
  return {
    slug: p.slug,
    name: p.name,
    region: p.region,
    image: p.image,
    tagline: p.tagline,
    overview: p.overview,
    highlights: p.highlights,
    bestTime: p.bestTime,
    styles: p.styles,
    faqs: p.faqs ?? [
      { q: `When is the best time to visit ${p.name}?`, a: p.bestTime },
      {
        q: "Can the journey be tailored?",
        a: "Entirely — our specialists shape every detail around your dates, pace and interests.",
      },
    ],
  };
}

