// Factory to keep the expanded catalogue concise while filling every Journey field.
function mk(p: {
  slug: string;
  title: string;
  destination: string;
  country: string;
  region: string;
  category: string;
  style: string[];
  duration: number;
  priceFrom: number | null;
  availability?: Availability;
  departures?: string[];
  image: string;
  featured?: boolean;
  bestseller?: boolean;
  overview: string;
  highlights: string[];
  itinerary: { day: string; title: string; text: string }[];
  inclusions?: string[];
  exclusions?: string[];
  accommodations: string[];
  faqs?: { q: string; a: string }[];
}): Journey {
  return {
    slug: p.slug,
    title: p.title,
    destination: p.destination,
    country: p.country,
    region: p.region,
    category: p.category,
    style: p.style,
    duration: p.duration,
    priceFrom: p.priceFrom,
    availability: p.availability ?? "Available",
    departures: p.departures ?? ["Year-round — enquire for dates"],
    featured: p.featured ?? false,
    bestseller: p.bestseller,
    image: p.image,
    overview: p.overview,
    highlights: p.highlights,
    itinerary: p.itinerary,
    inclusions: p.inclusions ?? [
      "Luxury accommodation throughout",
      "Private guides & expert local hosts",
      "Private transfers & internal travel",
      "Selected meals & signature experiences",
    ],
    exclusions: p.exclusions ?? [
      "International flights",
      "Travel insurance",
      "Visas where applicable",
      "Gratuities & personal expenses",
    ],
    accommodations: p.accommodations,
    faqs: p.faqs ?? [
      {
        q: "Can this journey be tailored?",
        a: "Entirely — it is a starting point our specialists shape around your dates, pace and interests.",
      },
      {
        q: "Is it suitable for special occasions?",
        a: "Yes — honeymoons, anniversaries and milestone celebrations are a speciality.",
      },
    ],
  };
}

